def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    beam = set()
    for r in range(h):
        if out[r][0] == 1 and out[r][w - 1] == 1:
            beam.update((r, c) for c in range(w))
    for c in range(w):
        if out[0][c] == 1 and out[h - 1][c] == 1:
            beam.update((r, c) for r in range(h))
    seen = set()
    for r in range(h):
        for c in range(w):
            if out[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and out[ny][nx] == 2 and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            if any((y + dy, x + dx) in beam for y, x in component for dy in (-1, 0, 1) for dx in (-1, 0, 1)):
                for y, x in component:
                    out[y][x] = 1
    for r, c in beam:
        out[r][c] = 1
    return out
